python3 -I - <<'EOF'
import json
rows=[]
for line in open('/workspace/logs/run_001/metrics.jsonl'):
    line=line.strip()
    if not line: continue
    rows.append(json.loads(line))
print('rows',len(rows),'steps',rows[0].get('step'),rows[-1].get('step'))
keys=['critic/rewards/mean','actor/entropy','actor/pg_loss','actor/ppo_kl','actor/grad_norm','actor/lr','weights_l2_norm','response_length/mean','response_length/clip_ratio','parity/logprob_abs_mean_nat','parity/logprob_abs_max_nat','parity/logprob_signed_mean_nat','parity/seq_ess_fraction','parity/mis_rejected_sequence_fraction','parity/sequence_log_ratio_p50','parity/sequence_log_ratio_min','parity/sequence_log_ratio_max','perf/time_per_step']
# print header
hdr=['step']+[k.split('/')[-1][:14] for k in keys]
print('\t'.join(hdr))
last=rows[-1]
def g(r,k):
    v=r.get(k)
    if isinstance(v,dict): v=v.get('value',v)
    return v
for r in rows:
    st=r.get('step')
    if st in (0,1,2,3,4,5,10,20,40,60,80,100,120,140,160,180,200,220,240,260,280,300,320,326,340,360,380,400,420,440):
        vals=[]
        for k in keys:
            v=g(r,k)
            if v is None: vals.append('-')
            elif isinstance(v,float): vals.append(f'{v:.4g}')
            else: vals.append(str(v))
        print('\t'.join([str(st)]+vals))
EOF

